import{z as B,x as A,o as t,c as d,q as o,j as l,D as e,d as i,s as n,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Gertler–Kiyotaki 银行中介","description":"","frontmatter":{"title":"Gertler–Kiyotaki 银行中介","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gertler-kiyotaki.md","filePath":"econ/gertler-kiyotaki.md","lastUpdated":1791063341000}'),p={name:"econ/gertler-kiyotaki.md"};function m(h,a,k,C,c,D){const E=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="gertler–kiyotaki-银行中介" tabindex="-1">Gertler–Kiyotaki 银行中介 <a class="header-anchor" href="#gertler–kiyotaki-银行中介" aria-label="Permalink to &quot;Gertler–Kiyotaki 银行中介&quot;">​</a></h1><div class="epigraph"><p>银行用净值吸收激励约束；净值被冲掉时，信贷供给收缩，即使借款企业的土地还在。</p><footer>—— Gertler and Kiyotaki, Financial Intermediation and Credit Policy in Business Cycle Analysis, Handbook of Monetary Economics 2010；Gertler and Karadi, JME 2011</footer></div><p><a href="/econ/kiyotaki-moore">上一课</a>的约束在最终借款人身上。危机里更刺眼的是中介。本课缺口是 <strong>GK</strong>：银行净值、激励约束、信贷政策。不重推土地抵押的代数，不把央行资产负债表工具写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KM 可以没有银行。现实信贷经中介。Gertler–Kiyotaki / Gertler–Karadi：银行家能转移资产，存款人只愿在净值足够时提供资金，形成对银行杠杆的激励约束。<span class="marginnote">「银行家能转移资产」翻译成大白话：银行家可能把好资产划进自己口袋（掏空银行），存款人心里有数。只有当银行自有本金足够厚、跑路不划算时，存款人才肯把钱放进来——杠杆上限本质上是一道「自有本金押金要求」。</span>冲击打净资产（贷款损失、资产价格），杠杆上限收紧，利差升，实体投资降。央行买私人资产或给资本，等于补充中介净值。缺口是把加速器从「企业土地」挪到「银行资本」。</p><p><span class="marginnote">Gertler and Karadi, <em>JME</em> 2011。Gertler and Kiyotaki, <em>Handbook</em> 2010；后续 GK 流动性风险与银行挤兑扩展。He and Krishnamurthy 的中介定价是连续时间姐妹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>银行最大化特许权价值，约束：转移激励 \\(\\Rightarrow\\) 资产 \\(\\le \\phi\\times\\) 净值。\\(\\phi\\) 可随价值内生。家庭持存款，不能直接持企业资本（或只能付更高成本）。冲击：资本质量、银行股票、挤兑。政策：信贷政策改变谁持有风险资产。线性化在约束平均松时低估危机；偶尔绑定或非线性必要。</p><p><span class="marginnote">杠杆放大代个数字：上限 \\(\\phi=10\\)，净值 50 亿的银行最多持有 500 亿资产；亏损把净值打到 30 亿，上限立刻缩到 300 亿——净值掉了 40%，信贷供给就得砍 200 亿。放大不来自神秘机制，只是 10 倍杠杆把净值每 1 元的波动乘成 10 元的信贷。</span></p>',9)),(t(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NW%5B%22%E9%93%B6%E8%A1%8C%E5%87%80%E5%80%BC%22%5D%20--%3E%20PHI%5B%22%E6%BF%80%E5%8A%B1%E6%9D%A0%E6%9D%86%20%CF%86%22%5D%0A%20%20PHI%20--%3E%20A%5B%22%E9%93%B6%E8%A1%8C%E8%B5%84%E4%BA%A7%20%2F%20%E4%BF%A1%E8%B4%B7%22%5D%0A%20%20A%20--%3E%20SPR%5B%22%E5%88%A9%E5%B7%AE%22%5D%0A%20%20SPR%20--%3E%20I%5B%22%E5%AE%9E%E4%BD%93%E6%8A%95%E8%B5%84%22%5D%0A%20%20CB%5B%22%E4%BF%A1%E8%B4%B7%E6%94%BF%E7%AD%96%22%5D%20--%3E%20NW%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"与 KM：可以两层约束都在——企业抵押加银行激励。定量危机模型常两层一起开。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"机制是净值稀缺。中介的专门性意味着家庭不能无摩擦取代银行持有资本，故银行净值有总量价格。利差是影子价格。宏观审慎（后课）针对 \\(\\phi\\) 或资本，非常规货币针对资产需求与净值。HANK：信贷收缩打劳动收入与房价，高 MPC 家庭放大——可叠，本课先代表或企业家侧。",-1)),(t(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E5%86%B2%E5%87%BB%3A%20%E8%B5%84%E4%BA%A7%E8%B4%A8%E9%87%8F%E6%81%B6%E5%8C%96%22%5D%20--%3E%20NW%5B%22%E9%93%B6%E8%A1%8C%E5%87%80%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20NW%20--%3E%20CAP%5B%22%E6%9D%A0%E6%9D%86%E4%B8%8A%E9%99%90%20%CF%86%C3%97%E5%87%80%E5%80%BC%20%E6%94%B6%E7%B4%A7%22%5D%0A%20%20CAP%20--%3E%20SELL%5B%22%E8%A2%AB%E8%BF%AB%E6%8A%9B%E5%94%AE%E8%B5%84%E4%BA%A7%22%5D%0A%20%20SELL%20--%3E%20PRICE%5B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20PRICE%20--%3E%20AGAIN%5B%22%E5%87%80%E5%80%BC%E5%86%8D%E8%A2%AB%E6%89%93%22%5D%0A%20%20AGAIN%20--%3E%20CAP%0A%20%20POL%5B%22%E5%A4%AE%E8%A1%8C%E4%BF%A1%E8%B4%B7%E6%94%BF%E7%AD%96%22%5D%20-.-%3E%7C%22%E8%A1%A5%E5%87%80%E5%80%BC%20%2F%20%E6%8E%A5%E8%B5%84%E4%BA%A7%22%7C%20NW%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">初学者容易以为「项目还在、土地还在，信贷就不该收缩」。GK 的要点恰恰是：约束绑在中介身上而不是借款人身上——银行净值被冲掉后，优质项目摆在那里也缺人有钱去放贷。这道「银行闸门」与 KM 的「企业抵押闸门」是两道独立的闸，危机模型常两道一起开。</span></p><p>识别：利差脉冲要用信用冲击的识别（叙事、符号），不是把每一个利差升都叫 GK。</p><p><span class="marginnote">Diamond–Dybvig 挤兑在主干已有。GK 扩展把挤兑接到总量净值。影子银行课再换主体。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写巴塞尔每一条风险权重。不把回购市场微观结构写完（后课 repo）。主权债持有使银行–主权回路，后课违约。不估计银行股票 alpha。</p><p>后课默认：中介净值是宏观状态；信贷政策与利率政策分工。下一课：住房作为抵押的专门化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GK：银行激励约束把净值接到信贷供给与利差。</li><li>信贷政策补净值或替中介持有风险。</li><li>可与 KM 企业抵押叠加。</li><li>出处：Gertler and Karadi, <em>JME</em> 2011。</li></ul>',8))])}const K=B(p,[["render",m]]);export{f as __pageData,K as default};
